		"#include <stdio.h>\n\n" +
		"typedef struct { int _0; int _1; } ogo_ret_int_int;\n\n" +
		"ogo_ret_int_int dm(int x);\n\n" +
		"ogo_ret_int_int dm(int x) {\n" +
		"\treturn (ogo_ret_int_int){(x / 2), (x + 1)};\n" +
		"}\n\n" +
		"int main(void) {\n" +
		"\tint a = 0;\n" +
		"\tint b = 0;\n" +
		"\togo_ret_int_int _ogo_t0 = dm(7);\n" +
		"\ta = _ogo_t0._0;\n" +
		"\tb = _ogo_t0._1;\n" +
		"\togo_ret_int_int _ogo_t1 = dm(a);\n" +
		"\tb = _ogo_t1._1;\n" +
		"\tprintf(\"%d\\n\", (a + b));\n" +
		"\treturn 0;\n" +
		"}\n"
