// TestEmitCConst pins constant declarations: package-level constants become
// file-scope `static const` (an untyped one defaulting to int, a computed one
// folded to its value, the predeclared bool true as 1), a local constant a
// block-scope `const`, and a constant's type flows into `x := CONST + ...` typing.
func TestEmitCConst(t *testing.T) {
	src := `const led = 56
const area = 10 * 20
const on = true

func main() {
	const step = 2
	x := led + step
	println(x)
	println(area)
	if on {
		println(1)
	}
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"static const int led = 56;\n" +
		"static const int area = 200;\n" + // a constant integer expression folds to its value
		"static const _Bool on = 1;\n\n" +
		"int main(void) {\n" +
		"\tconst int step = 2;\n" +
		"\tint x = (led + step);\n" +
		"\tprintf(\"%d\\n\", x);\n" +
		"\tprintf(\"%d\\n\", area);\n" +
		"\tif (on) {\n" +
		"\t\tprintf(\"%d\\n\", 1);\n" +
		"\t}\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC const:\n got %q\nwant %q", got, want)
	}
}

