// TestEmitCPointer pins pointers to structs: a `*T` parameter maps to `T*`,
// `&x` takes an address, a field access through a pointer emits `->` (Go's
// implicit dereference), and `p := &x` infers a pointer type.
func TestEmitCPointer(t *testing.T) {
	src := `type C struct {
	n int
}

func bump(p *C) {
	p.n = p.n + 1
}

func main() {
	var c C
	bump(&c)
	p := &c
	p.n = p.n + 10
	println(c.n)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef struct C C;\nstruct C { int n; };\n\n" +
		"void bump(C* p);\n\n" +
		"void bump(C* p) {\n" +
		"\tp->n = (p->n + 1);\n" +
		"}\n\n" +
		"int main(void) {\n" +
		"\tC c = {0};\n" +
		"\tbump(&c);\n" +
		"\tC* p = &c;\n" +
		"\tp->n = (p->n + 10);\n" +
		"\tprintf(\"%d\\n\", c.n);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC pointer:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCUnary pins prefix unary operators: `-x` and Go's bitwise complement
// `^x` (which C spells `~x`).
func TestEmitCUnary(t *testing.T) {
	src := `func main() {
	var x int = 5
	y := -x
	z := ^x
	println(y + z)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"int main(void) {\n" +
		"\tint x = 5;\n" +
		"\tint y = -x;\n" +
		// Go's ^x is emitted as an explicit XOR with all ones, not C's ~x: see
		// emitComplement for the backend miscompile that spelling routes around.
		"\tint z = ((int)-1 ^ (x));\n" +
		"\tprintf(\"%d\\n\", (y + z));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC unary:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCArray pins fixed arrays: `var a [N]T` becomes `T a[N] = {0}` (the bound
// folded from an integer constant, since flexcc rejects a static-const bound),
// indexed read and write `a[i]`, and a field-like `x := a[i]` element typing.
func TestEmitCArray(t *testing.T) {
	src := `const N = 4

func main() {
	var a [N]int
	var i int
	for i < N {
		a[i] = i * i
		i++
	}
	x := a[2]
	println(x)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"static const int N = 4;\n\n" +
		"int main(void) {\n" +
		"\tint a[4] = {0};\n" +
		"\tint i = 0;\n" +
		"\twhile (i < N) {\n" +
		"\t\ta[i] = (i * i);\n" +
		"\t\ti++;\n" +
		"\t}\n" +
		"\tint x = a[2];\n" +
		"\tprintf(\"%d\\n\", x);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC array:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCArrayParam pins Go array value semantics for a `[N]T` parameter. C
// cannot pass an array by value and flexcc cannot wrap it in a struct, so the
// parameter arrives by pointer and the function copies it into a same-named local
// on entry (memcpy); the caller's array is thus untouched by the callee.
func TestEmitCArrayParam(t *testing.T) {
	src := `func sum(a [3]int) int {
	return a[0] + a[1] + a[2]
}

func main() {
	var a [3]int
	a[0] = 1
	a[1] = 2
	a[2] = 3
	println(sum(a))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n" +
		"#include <string.h>\n\n" +
		"int sum(int* _ogo_a);\n\n" +
		"int sum(int* _ogo_a) {\n" +
		"\tint a[3];\n" +
		"\tmemcpy(a, _ogo_a, sizeof(a));\n" +
		"\treturn (a[0] + a[1] + a[2]);\n" +
		"}\n\n" +
		"int main(void) {\n" +
		"\tint a[3] = {0};\n" +
		"\ta[0] = 1;\n" +
		"\ta[1] = 2;\n" +
		"\ta[2] = 3;\n" +
		"\tprintf(\"%d\\n\", sum(a));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC array param:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCSwitch pins a value switch: it lowers to an if / else-if chain (OctoGo
