// TestEmitCPackageDestructure pins `var a, b = f()` at package scope: C forbids a
// call in a file-scope initializer, so each variable is declared static and
// zero-initialized and the call is bound to a temporary and distributed in the
// synthesized package initializer -- with a distinct temporary per call and a blank
// target dropped, exactly as emitDestructure does for locals.
func TestEmitCPackageDestructure(t *testing.T) {
	src := `func sums(a, b int) (int, int) {
	return a + b, a - b
}

var sum, diff = sums(10, 3)
var _, gap = sums(20, 5)

func main() {
	println(sum)
	println(diff)
	println(gap)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef struct { int _0; int _1; } ogo_ret_int_int;\n\n" +
		// The prototypes precede the globals: a package variable may be
		// initialized with a function, and C wants it declared first.
		"ogo_ret_int_int sums(int a, int b);\n\n" +
		"static int sum = 0;\n" +
		"static int diff = 0;\n" +
		"static int gap = 0;\n\n" +
		"static void ogo_pkg_init(void) {\n" +
		"\togo_ret_int_int _ogo_t0 = sums(10, 3);\n" +
		"\tsum = _ogo_t0._0;\n" +
		"\tdiff = _ogo_t0._1;\n" +
		"\togo_ret_int_int _ogo_t1 = sums(20, 5);\n" +
		"\tgap = _ogo_t1._1;\n" +
		"}\n\n" +
		"ogo_ret_int_int sums(int a, int b) {\n" +
		"\treturn (ogo_ret_int_int){(a + b), (a - b)};\n" +
		"}\n\n" +
		"int main(void) {\n" +
		"\togo_pkg_init();\n" +
		"\tprintf(\"%d\\n\", sum);\n" +
		"\tprintf(\"%d\\n\", diff);\n" +
		"\tprintf(\"%d\\n\", gap);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC package destructure:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCLen pins the builtin len: an array's length is its compile-time bound,
