// TestEmitCMinMax pins the builtins min and max: a two-argument helper per type
// (a<b?a:b / a>b?a:b) that a variadic call folds left over -- min(8, 3, 5) is
// min(min(8, 3), 5). The helper, not an inline ternary, is what evaluates each
// argument once.
// TestEmitCSetBaud pins p2.SetBaud to the intrinsic, as a GOLDEN rather than a run
// case: it changes the rate of the very link the on-board harness reads the answer
// back on, so running it would break the test that ran it. The Viskomat protocol
// this exists for wants 921600, where the loader leaves the link at 230400.
func TestEmitCSetBaud(t *testing.T) {
	src := `import "p2"

func main() {
	p2.SetBaud(921600)
	printf("x %d\r", 1)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	for _, want := range []string{"#include <propeller2.h>", "_setbaud(921600);"} {
		if !strings.Contains(buf.String(), want) {
			t.Errorf("EmitC: want it to contain %q\ngot:\n%s", want, buf.String())
		}
	}
}

// TestEmitCADC pins the ADC half of the smart-pin vocabulary: the input ranges, the
// two internal references a ratiometric reading is scaled between, and the sampling
// mode. A GOLDEN rather than a run case for the reason the DAC constants are not run
// either -- what a converter returns is an analog fact about the board, not a value
// a host shim can stand in for. It was verified on a P2-EDGE instead: a floating pin
// read 1647 mV between references measured at 3022 and 13661 counts, which is
// mid-rail to three digits.
// TestEmitCReadByte pins p2.ReadByte to the intrinsic. A GOLDEN rather than a run
// case because neither harness can feed it: the host shim has no serial line to type
// at, and the on-board one only reads the board's output back. It was verified by
// hand on a P2-EDGE instead -- a loop reading into an array received "PING\rOK\r" as
// 80 73 78 71 13 79 75 13, every byte and in order.
func TestEmitCReadByte(t *testing.T) {
	src := `import "p2"

func main() {
	for {
		c := p2.ReadByte(0)
		if c < 0 {
			break
		}
		println(c)
	}
	println(p2.ReadByte(250))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	// Typed int, not unsigned: the -1 that says "nothing arrived" is the whole
	// protocol, and an unsigned result would compare greater than zero forever.
	for _, want := range []string{"_rxraw(0)", "_rxraw(250)", "#include <propeller2.h>"} {
		if !strings.Contains(buf.String(), want) {
			t.Errorf("EmitC: want it to contain %q\ngot:\n%s", want, buf.String())
		}
	}
	if strings.Contains(buf.String(), "unsigned") {
		t.Errorf("EmitC: ReadByte must type as a signed int:\n%s", buf.String())
	}
}

// TestEmitCWriteByte pins p2.WriteByte to _txraw and to nothing else. The intrinsic
// is the whole point: the two obvious alternatives both corrupt a packet, quietly.
// printf's %c writes a rune, so 200 goes out UTF-8 as 195 136; putchar translates a
// 10 into 13 10. Measured on a P2-EDGE, _txraw wrote 1..255 as exactly 255 bytes
// where putchar wrote 256, and a frame of {0xAA, 4, 10, 200, 0xAA, 13, sum} arrived
// byte for byte.
func TestEmitCWriteByte(t *testing.T) {
	src := `import "p2"

func main() {
	p2.WriteByte(0xAA)
	p2.WriteByte(10)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	for _, want := range []string{"_txraw(0xAA)", "_txraw(10)"} {
		if !strings.Contains(buf.String(), want) {
			t.Errorf("EmitC: want it to contain %q\ngot:\n%s", want, buf.String())
		}
	}
	if strings.Contains(buf.String(), "putchar") || strings.Contains(buf.String(), "ogo_print_rune") {
		t.Errorf("EmitC: WriteByte must not go through a translating path:\n%s", buf.String())
	}
}

// TestEmitCPinDrive pins the pull-up and pull-down recipes, which are the reason the
// drive constants exist: the P2 has no pull-up bit, so one is a weak HIGH drive with
// a floating LOW drive, and getting either half wrong leaves a pin that reads
// whatever it likes. Verified on a P2-EDGE: pulled down the pin read 0 where the same
// pin left floating read 1.
func TestEmitCPinDrive(t *testing.T) {
	src := `import "p2"

func main() {
	p2.WritePinMode(40, p2.DriveHigh15K|p2.DriveLowFloat)
	p2.PinHigh(40)
	p2.WritePinMode(41, p2.DriveHighFloat|p2.DriveLow15K)
	p2.PinLow(41)
	println(p2.PinIn(40), p2.PinIn(41))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	for _, want := range []string{
		"_wrpin(40, (0x1000 | 0x700))", // a weak high, a floating low: a pull-up
		"_wrpin(41, (0x3800 | 0x200))", // and the mirror of it
		"_pinr(40)",
	} {
		if !strings.Contains(buf.String(), want) {
			t.Errorf("EmitC: want it to contain %q\ngot:\n%s", want, buf.String())
		}
	}
}

func TestEmitCADC(t *testing.T) {
	src := `import "p2"

func main() {
	p2.PinStart(40, p2.ADC1X|p2.ADCSample, 13, 0)
	p2.PinStart(40, p2.ADCGround|p2.ADCSample, 13, 0)
	p2.PinStart(40, p2.ADCSupply|p2.ADCSample, 13, 0)
	println(int(p2.ReadPin(40)))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	// The range or reference in the high bits, the mode in the low ones. Either half
	// alone still compiles and still runs, which is what makes the pair worth pinning.
	for _, want := range []string{
		"_pinstart(40, (0x118000 | 0x30), 13, 0)",
		"_pinstart(40, (0x100000 | 0x30), 13, 0)",
		"_pinstart(40, (0x108000 | 0x30), 13, 0)",
		"_rdpin(40)",
	} {
		if !strings.Contains(buf.String(), want) {
			t.Errorf("EmitC: want it to contain %q\ngot:\n%s", want, buf.String())
		}
	}
}

func TestEmitCMinMax(t *testing.T) {
	src := `func main() {
	println(min(8, 3, 5), max(2, 9))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"static int ogo_min_int(int a, int b) { return a < b ? a : b; }\n" +
		"static int ogo_max_int(int a, int b) { return a > b ? a : b; }\n\n" +
		"int main(void) {\n" +
		"\tprintf(\"%d %d\\n\", ogo_min_int(ogo_min_int(8, 3), 5), ogo_max_int(2, 9));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC min/max:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCUnsupportedBuiltins pins that a predeclared builtin the emitter does not
// implement is refused by name rather than emitted as a call to a nonexistent C
// function, which is what copy silently did before it was implemented. The checker
// exempts every builtin name from its undefined check, so the emitter is the only
// place this can be caught. A user function that shadows a builtin name is a real
// call and must still emit.
func TestEmitCUnsupportedBuiltins(t *testing.T) {
	refused := map[string]string{
		"delete":  "func main() {\n\tvar m int\n\tdelete(m, 1)\n}\n",
		"recover": "func main() {\n\trecover()\n}\n",
		"close":   "func f(ch chan int) {\n\tclose(ch)\n}\n\nfunc main() {\n\tvar ch chan int\n\tf(ch)\n}\n",
	}
	for name, src := range refused {
		t.Run(name, func(t *testing.T) {
			fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
			pkg, err := Build(-1, []string{"main.ogo"}, fsys)
			if err != nil {
				t.Fatalf("Build: %v", err)
			}
			var buf bytes.Buffer
			err = EmitC(pkg, &buf)
			if err == nil {
				t.Fatalf("EmitC accepted the unimplemented %s builtin:\n%s", name, buf.String())
			}
			if want := "the " + name + " builtin is not supported yet"; !strings.Contains(err.Error(), want) {
				t.Errorf("EmitC error %q does not name the %s builtin", err, name)
			}
		})
	}

	t.Run("user shadow", func(t *testing.T) {
		src := "func min(a int, b int) int {\n\tif a < b {\n\t\treturn a\n\t}\n\treturn b\n}\n\nfunc main() {\n\tprintln(min(3, 5))\n}\n"
		fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
		pkg, err := Build(-1, []string{"main.ogo"}, fsys)
		if err != nil {
			t.Fatalf("Build: %v", err)
		}
		var buf bytes.Buffer
		if err := EmitC(pkg, &buf); err != nil {
			t.Fatalf("EmitC refused a user function shadowing a builtin: %v", err)
		}
		if !strings.Contains(buf.String(), "min(3, 5)") {
			t.Errorf("expected a real call to the user min:\n%s", buf.String())
		}
	})
}

// TestEmitCSliceInfer pins short-declaration slice inference: "s := a[1:4]" gives s
// a slice type (not its element's), so it can be indexed and re-sliced ("s2 :=
// s[1:]"). Previously the checker mis-typed s as a scalar and rejected s[i].
// Verified: for a[2]=7, s=a[1:4] has len 3, s2=s[1:] has cap 3, and s[1]==7.
func TestEmitCSliceInfer(t *testing.T) {
	src := `func main() {
	var a [5]int
	a[2] = 7
	s := a[1:4]
	s2 := s[1:]
	println(len(s))
	println(cap(s2))
	println(s[1])
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef struct { int* ptr; int len; int cap; } ogo_slice_int;\n\n" +
		"int main(void) {\n" +
		"\tint a[5] = {0};\n" +
		"\ta[2] = 7;\n" +
		"\togo_slice_int s = (ogo_slice_int){a + 1, 4 - 1, 5 - 1};\n" +
		"\togo_slice_int s2 = (ogo_slice_int){s.ptr + 1, s.len - 1, s.cap - 1};\n" +
		"\tprintf(\"%d\\n\", (s).len);\n" +
		"\tprintf(\"%d\\n\", (s2).cap);\n" +
		"\tprintf(\"%d\\n\", s.ptr[1]);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC slice infer:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCChecks pins the runtime check subsystem. Checked() wraps a variable
// index in ogo_bound and a variable divisor in ogo_nonzero, both calling ogo_panic;
// a constant index or divisor is left unchecked. Release() makes ogo_panic reboot
// (_reboot) instead of halting (abort). The default emit (no options) omits the
// checks entirely -- the ogo build CLI turns them on by default.
func TestEmitCChecks(t *testing.T) {
	src := `func main() {
	var a [4]int
	var i int
	a[i] = 9
	x := a[i] / i
	println(x)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf, Checked()); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <propeller2.h>\n" +
		"#include <stdio.h>\n" +
		"#include <stdlib.h>\n" +
		"\n" +
		"static void ogo_panic(const char* msg) {\n" +
		"\tprintf(\"panic: %s\\n\", msg);\n" +
		"\tfflush(stdout); // abort discards a buffered message; a pipe buffers\n" +
		"\t_waitms(10); // let the message flush over the serial line first\n" +
		"\tabort(); // -> _Exit -> _cogstop: halt the offending cog\n" +
		"}\n" +
		"static int ogo_bound(int i, int n) {\n" +
		"\tif ((unsigned)i >= (unsigned)n) ogo_panic(\"index out of range\");\n" +
		"\treturn i;\n" +
		"}\n" +
		"static int ogo_div_int(int a, int b) {\n" +
		"\tif (b == 0) ogo_panic(\"integer divide by zero\");\n" +
		"\tif (b == -1) { unsigned t = (unsigned)0 - (unsigned)a; return (int)t; }\n" +
		"\treturn a / b;\n" +
		"}\n" +
		"\n" +
		"int main(void) {\n" +
		"\tint a[4] = {0};\n" +
		"\tint i = 0;\n" +
		"\ta[ogo_bound(i, 4)] = 9;\n" +
		"\tint x = ogo_div_int(a[ogo_bound(i, 4)], i);\n" +
		"\tprintf(\"%d\\n\", x);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC checked:\n got %q\nwant %q", got, want)
	}

	// A release build reboots on a panic instead of halting the cog.
	var rel bytes.Buffer
	if err := EmitC(pkg, &rel, Checked(), Release()); err != nil {
		t.Fatalf("EmitC release: %v", err)
	}
	if !bytes.Contains(rel.Bytes(), []byte("_reboot();")) || bytes.Contains(rel.Bytes(), []byte("abort();")) {
		t.Errorf("release build should reboot, not abort:\n%s", rel.String())
	}

	// The default (unchecked) build emits neither check helper.
	var un bytes.Buffer
	if err := EmitC(pkg, &un); err != nil {
		t.Fatalf("EmitC unchecked: %v", err)
	}
	if bytes.Contains(un.Bytes(), []byte("ogo_bound")) || bytes.Contains(un.Bytes(), []byte("integer divide by zero")) {
		t.Errorf("default build should emit no checks:\n%s", un.String())
	}
}

// TestEmitCConstSliceBounds pins the bounds that are wrong however the program runs
// being reported rather than left to trap. Go rejects each of these at compile time,
// in these words and at these columns.
//
// Only an operand whose extent is a compile-time constant qualifies -- an array's.
// A slice's length and capacity are run-time values, so a bound against them can
// only be checked as the program runs, and Go says nothing about those either.
func TestEmitCConstSliceBounds(t *testing.T) {
	for _, test := range []struct{ name, src, want string }{
		{
			name: "high past the extent",
			src:  "\tvar a [4]int\n\ts := a[1:9]\n\tprintln(len(s))",
			want: "3:11: invalid argument: index 9 out of bounds [0:5]",
		},
		{
			name: "low above high",
			src:  "\tvar a [8]int\n\ts := a[3:1]\n\tprintln(len(s))",
			want: "3:11: invalid slice indices: 1 < 3",
		},
		{
			name: "capacity bound past the extent",
			src:  "\tvar a [4]int\n\ts := a[0:2:9]\n\tprintln(len(s))",
			want: "3:13: invalid argument: index 9 out of bounds [0:5]",
		},
		{
			name: "high above the capacity bound",
			src:  "\tvar a [8]int\n\ts := a[0:5:3]\n\tprintln(len(s))",
			want: "3:13: invalid slice indices: 3 < 5",
		},
		{
			name: "negative bound",
			src:  "\tvar a [8]int\n\ts := a[0-1 : 2]\n\tprintln(len(s))",
			want: "3:9: invalid argument: index -1 must not be negative",
		},
		{
			name: "a folded constant expression",
			src:  "\tvar a [4]int\n\ts := a[1 : 2+8]\n\tprintln(len(s))",
			want: "3:13: invalid argument: index 10 out of bounds [0:5]",
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			src := "func main() {\n" + test.src + "\n}\n"
			fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
			pkg, err := Build(-1, []string{"main.ogo"}, fsys)
			if err != nil {
				t.Fatalf("Build: %v", err)
			}
			var buf bytes.Buffer
			if err := EmitC(pkg, &buf, Checked()); err == nil {
				t.Fatalf("EmitC accepted %q:\n%s", test.src, buf.String())
			} else if !strings.Contains(err.Error(), test.want) {
				t.Errorf("EmitC error %q does not contain %q", err, test.want)
			}
		})
	}

	// A bound the compiler cannot settle is left to the run-time check, whatever it
	// is: a slice operand has no compile-time extent, and neither has a string one.
	for _, src := range []string{
		"\ts := make([]int, 2, 4)\n\tt := s[0:9]\n\tprintln(len(t))",
		"\ts := \"hello\"\n\tt := s[1:9]\n\tprintln(len(t))",
		"\tvar a [4]int\n\ti := 9\n\ts := a[1:i]\n\tprintln(len(s))",
	} {
		fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte("func main() {\n" + src + "\n}\n")}}
		pkg, err := Build(-1, []string{"main.ogo"}, fsys)
		if err != nil {
			t.Fatalf("Build: %v", err)
		}
		var buf bytes.Buffer
		if err := EmitC(pkg, &buf, Checked()); err != nil {
			t.Errorf("EmitC refused %q, which only the run-time check can decide: %v", src, err)
		}
	}
}

// TestEmitCSliceBounds pins where a slice expression's bounds are checked. A bound
// the compiler cannot settle goes through ogo_reslice_<T>, which panics on a bound
// out of range; one it can settle is spelled inline as before, which is why `a[:]`
// and a constant slice of an array carry no check.
//
// The helper is also what makes each bound evaluated exactly once, so a bound that
// can change state reaches it even with the checks compiled out -- the inline form
// names low in all three header fields.
func TestEmitCSliceBounds(t *testing.T) {
	src := `func main() {
	var a [4]int
	i := 1
	s := a[i:3]
	t := a[:]
	u := a[1:3]
	println(len(s), len(t), len(u))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf, Checked()); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <propeller2.h>\n" +
		"#include <stdio.h>\n" +
		"#include <stdlib.h>\n" +
		"\n" +
		"typedef struct { int* ptr; int len; int cap; } ogo_slice_int;\n" +
		"\n" +
		"static void ogo_panic(const char* msg) {\n" +
		"\tprintf(\"panic: %s\\n\", msg);\n" +
		"\tfflush(stdout); // abort discards a buffered message; a pipe buffers\n" +
		"\t_waitms(10); // let the message flush over the serial line first\n" +
		"\tabort(); // -> _Exit -> _cogstop: halt the offending cog\n" +
		"}\n" +
		"static ogo_slice_int ogo_reslice_int(int* p, int c, int lo, int hi) {\n" +
		"\tif ((unsigned)hi > (unsigned)c || (unsigned)lo > (unsigned)hi) ogo_panic(\"slice bounds out of range\");\n" +
		"\treturn (ogo_slice_int){p + lo, hi - lo, c - lo};\n" +
		"}\n" +
		"\n" +
		"int main(void) {\n" +
		"\tint a[4] = {0};\n" +
		"\tint i = 1;\n" +
		"\togo_slice_int s = ogo_reslice_int(a, 4, i, 3);\n" +
		"\togo_slice_int t = (ogo_slice_int){a, 4, 4};\n" +
		"\togo_slice_int u = (ogo_slice_int){a + 1, 3 - 1, 4 - 1};\n" +
		"\tprintf(\"%d %d %d\\n\", (s).len, (t).len, (u).len);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC checked:\n got %q\nwant %q", got, want)
	}

	// The default (unchecked) build spells every one of these inline.
	var un bytes.Buffer
	if err := EmitC(pkg, &un); err != nil {
		t.Fatalf("EmitC unchecked: %v", err)
	}
	if bytes.Contains(un.Bytes(), []byte("ogo_reslice")) {
		t.Errorf("default build should emit no slice check:\n%s", un.String())
	}

	// A bound that can change state still goes through the helper there, so it is
	// evaluated once -- but the helper carries no check.
	effect := `func next() int { return 1 }

func main() {
	var a [8]int
	s := a[next():5]
	println(len(s))
}
`
	fsys = fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(effect)}}
	if pkg, err = Build(-1, []string{"main.ogo"}, fsys); err != nil {
		t.Fatalf("Build: %v", err)
	}
	var eff bytes.Buffer
	if err := EmitC(pkg, &eff); err != nil {
		t.Fatalf("EmitC unchecked: %v", err)
	}
	if !bytes.Contains(eff.Bytes(), []byte("ogo_reslice_int(a, 8, next(), 5)")) {
		t.Errorf("a side-effecting bound should be evaluated once:\n%s", eff.String())
	}
	if bytes.Contains(eff.Bytes(), []byte("slice bounds out of range")) {
		t.Errorf("default build should emit no slice check:\n%s", eff.String())
	}

	// A third bound sets the capacity, so it takes the helper's three-bound twin and
	// its longer check; one the compiler can settle stays inline, with the bound in
	// the capacity field where the operand's own capacity would otherwise be.
	third := `func main() {
	var a [8]int
	i := 1
	s := a[i:3:5]
	t := a[1:3:5]
	println(len(s), cap(t))
}
`
	fsys = fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(third)}}
	if pkg, err = Build(-1, []string{"main.ogo"}, fsys); err != nil {
		t.Fatalf("Build: %v", err)
	}
	var cap3 bytes.Buffer
	if err := EmitC(pkg, &cap3, Checked()); err != nil {
		t.Fatalf("EmitC: %v", err)
	}
	for _, want := range []string{
		"static ogo_slice_int ogo_reslice3_int(int* p, int c, int lo, int hi, int mx) {\n" +
			"\tif ((unsigned)mx > (unsigned)c || (unsigned)hi > (unsigned)mx || (unsigned)lo > (unsigned)hi) ogo_panic(\"slice bounds out of range\");\n" +
			"\treturn (ogo_slice_int){p + lo, hi - lo, mx - lo};\n}\n",
		"ogo_slice_int s = ogo_reslice3_int(a, 8, i, 3, 5);\n",
		"ogo_slice_int t = (ogo_slice_int){a + 1, 3 - 1, 5 - 1};\n",
	} {
		if !bytes.Contains(cap3.Bytes(), []byte(want)) {
			t.Errorf("missing %q in:\n%s", want, cap3.String())
		}
	}
}

// printSliceIntHelpers is the generated ogo_print_slice_int / ogo_println_slice_int
// pair, pinned here so the print tests can share it.
const printSliceIntHelpers = "static void ogo_print_slice_int(ogo_slice_int s) {\n" +
	"\tprintf(\"[\");\n" +
	"\tfor (int _i = 0; _i < s.len; _i++) {\n" +
	"\t\tif (_i) printf(\" \");\n" +
	"\t\tprintf(\"%d\", s.ptr[_i]);\n" +
	"\t}\n" +
	"\tprintf(\"]\");\n" +
	"}\n" +
	"static void ogo_println_slice_int(ogo_slice_int s) { ogo_print_slice_int(s); printf(\"\\n\"); }\n"

// TestEmitCPrintMulti pins print/println of several integer arguments: they fold
// into a single space-separated printf, with the trailing newline only for println.
func TestEmitCPrintMulti(t *testing.T) {
	src := `func main() {
	var a int = 1
	var b int = 2
	println(a, b)
	print(a, b)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"int main(void) {\n" +
		"\tint a = 1;\n" +
		"\tint b = 2;\n" +
		"\tprintf(\"%d %d\\n\", a, b);\n" +
		"\tprintf(\"%d%d\", a, b);\n" + // print separates nothing; only println does
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC print multi:\n got %q\nwant %q", got, want)
	}
}

