// TestEmitCPrintElems pins printing a slice of a non-int element: a bool renders as
// the word true/false (as the scalar bool does), a string as its exact bytes
// (%.*s, like ogo_print_str), rather than a meaningless %d. The integer widths
// reuse scalarPrintVerb and are exercised behaviourally by the run suite.
func TestEmitCPrintElems(t *testing.T) {
	src := `func main() {
	bs := []bool{true, false}
	println(bs)
	ss := []string{"hi"}
	println(ss)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef struct { const char* str; int len; } ogo_string;\n" +
		"typedef struct { _Bool* ptr; int len; int cap; } ogo_slice__Bool;\n" +
		"typedef struct { ogo_string* ptr; int len; int cap; } ogo_slice_ogo_string;\n\n" +
		"static void ogo_print_slice__Bool(ogo_slice__Bool s) {\n" +
		"\tprintf(\"[\");\n" +
		"\tfor (int _i = 0; _i < s.len; _i++) {\n" +
		"\t\tif (_i) printf(\" \");\n" +
		"\t\tprintf(\"%s\", s.ptr[_i] ? \"true\" : \"false\");\n" +
		"\t}\n" +
		"\tprintf(\"]\");\n" +
		"}\n" +
		"static void ogo_println_slice__Bool(ogo_slice__Bool s) { ogo_print_slice__Bool(s); printf(\"\\n\"); }\n" +
		"static void ogo_print_slice_ogo_string(ogo_slice_ogo_string s) {\n" +
		"\tprintf(\"[\");\n" +
		"\tfor (int _i = 0; _i < s.len; _i++) {\n" +
		"\t\tif (_i) printf(\" \");\n" +
		"\t\tfor (int _j = 0; _j < s.ptr[_i].len; _j++) { putchar(s.ptr[_i].str[_j]); }\n" +
		"\t}\n" +
		"\tprintf(\"]\");\n" +
		"}\n" +
		"static void ogo_println_slice_ogo_string(ogo_slice_ogo_string s) { ogo_print_slice_ogo_string(s); printf(\"\\n\"); }\n\n" +
		"int main(void) {\n" +
		"\t_Bool ogo_backing_0[2] = {1, 0};\n" +
		"\togo_slice__Bool bs = {ogo_backing_0, 2, 2};\n" +
		"\togo_println_slice__Bool(bs);\n" +
		"\togo_string ogo_backing_1[1] = {{\"hi\", 2}};\n" +
		"\togo_slice_ogo_string ss = {ogo_backing_1, 1, 1};\n" +
		"\togo_println_slice_ogo_string(ss);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC print elems:\n got %q\nwant %q", got, want)
	}
}

