// TestEmitCDerefAssign pins assignment through a pointer receiver `*c = v`: the
// leading star is kept so the write goes through the pointer to the pointee (a
// regression guard -- dropping it emitted `c = v`, which mutated nothing), whether
// the method is called on a value (&cnt) or a pointer (pp).
func TestEmitCDerefAssign(t *testing.T) {
	src := `type Counter int

func (c *Counter) Set(v int) {
	*c = v
}

func (c Counter) Get() int {
	return c + 0
}

func main() {
	var cnt Counter = 0
	cnt.Set(7)
	println(cnt.Get())
	pp := &cnt
	pp.Set(42)
	println(cnt.Get())
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef int Counter;\n\n" +
		"void Counter_Set(Counter* c, int v);\n" +
		"int Counter_Get(Counter c);\n\n" +
		"void Counter_Set(Counter* c, int v) {\n" +
		"\t(*c) = v;\n" +
		"}\n\n" +
		"int Counter_Get(Counter c) {\n" +
		"\treturn (c + 0);\n" +
		"}\n\n" +
		"int main(void) {\n" +
		"\tCounter cnt = 0;\n" +
		"\tCounter_Set(&cnt, 7);\n" +
		"\tprintf(\"%d\\n\", Counter_Get(cnt));\n" +
		"\tCounter* pp = &cnt;\n" +
		"\tCounter_Set(pp, 42);\n" +
		"\tprintf(\"%d\\n\", Counter_Get(cnt));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC deref assign:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCSliceField pins a scalar-element slice struct field `data []int`: its
// ogo_slice_int header typedef is emitted before the struct that embeds it by value,
// the whole-slice field assignment `b.data = s` copies the header, and len(b.data)
// reads through it. (Direct b.data[i] / append(b.data, ...) come later; elements are
// reached here via a local alias, which shares the backing.)
func TestEmitCSliceField(t *testing.T) {
	src := `type Buf struct {
	data []int
	n    int
}

func main() {
	var b Buf
	s := make([]int, 3, 3)
	s[0] = 10
	s[1] = 20
	b.data = s
	b.n = len(b.data)
	println(b.n)
	t := b.data
	println(t[0] + t[1])
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n\n" +
		"#include <stdio.h>\n\n" +
		"typedef struct Buf Buf;\n" +
		"typedef struct { int* ptr; int len; int cap; } ogo_slice_int;\n" +
		"struct Buf { ogo_slice_int data; int n; };\n\n" +
		"int main(void) {\n" +
		"\tBuf b = {0};\n" +
		"\tint ogo_backing_0[3] = {0};\n" +
		"\togo_slice_int s = {ogo_backing_0, 3, 3};\n" +
		"\ts.ptr[0] = 10;\n" +
		"\ts.ptr[1] = 20;\n" +
		"\tb.data = s;\n" +
		"\tb.n = (b.data).len;\n" +
		"\tprintf(\"%d\\n\", b.n);\n" +
		"\togo_slice_int t = b.data;\n" +
		"\tprintf(\"%d\\n\", (t.ptr[0] + t.ptr[1]));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC slice field:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCSliceFieldIndex pins direct indexing of a slice struct field, read and
