// TestEmitCResliceField pins re-slicing a struct field: `b.data[1:3]` over a slice
// field and `b.arr[1:4]` over an array field. Only a variable base could be sliced
// before, so a field one reached emitSliceExpr's default arm and failed.
//
// The two bases differ in what bounds the result: a slice field carries its own
// cap forward, so the view may still grow to the end of the shared backing, while
// an array field's extent bounds both its length and its capacity.
func TestEmitCResliceField(t *testing.T) {
	src := `type Buf struct {
	data []int
	arr  [4]int
}

func main() {
	var b Buf
	b.data = make([]int, 4, 4)
	t := b.data[1:3]
	u := b.arr[1:4]
	println(len(t) + len(u))
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <stdio.h>\n" +
		"\n" +
		"typedef struct Buf Buf;\n" +
		"typedef struct { int* ptr; int len; int cap; } ogo_slice_int;\n" +
		"struct Buf { ogo_slice_int data; int arr[4]; };\n" +
		"\n" +
		"int main(void) {\n" +
		"\tBuf b = {0};\n" +
		"\tint ogo_backing_0[4] = {0};\n" +
		"\tb.data = (ogo_slice_int){ogo_backing_0, 4, 4};\n" +
		"\togo_slice_int t = (ogo_slice_int){b.data.ptr + 1, 3 - 1, b.data.cap - 1};\n" +
		"\togo_slice_int u = (ogo_slice_int){b.arr + 1, 4 - 1, 4 - 1};\n" +
		"\tprintf(\"%d\\n\", ((t).len + (u).len));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC re-slice a field:\n got %q\nwant %q", got, want)
	}
}

// TestEmitCIndexedIncDec pins ++ and -- on indexed targets that are not a bare
// local: a slice or array struct field element (`b.arr[0]++`), and an indexed
// element's field (`b.pts[1].x++`, `s[0].x--`). The grammar admits ++/-- on any
// assignment target, but only the bare-local paths implemented them; every other
// indexed target rejected the form and accepted plain `=` alone.
//
// Each of the three indexed-assignment paths had rewritten the same ++/--/= tail
// itself, which is why extending one did not extend the others. They now share
// assignTail, which classifies the PostfixOp before anything is emitted so an
// unsupported form cannot leave a half-written statement behind.
func TestEmitCIndexedIncDec(t *testing.T) {
	src := `type Point struct {
	x int
}

type Buf struct {
	arr [3]int
	pts []Point
}

func main() {
	var b Buf
	b.pts = make([]Point, 2, 2)
	b.arr[0]++
	b.pts[1].x++
	s := make([]Point, 2, 2)
	s[0].x--
	println(b.arr[0] + b.pts[1].x + s[0].x)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <stdio.h>\n" +
		"\n" +
		"typedef struct Point Point;\n" +
		"typedef struct Buf Buf;\n" +
		"struct Point { int x; };\n" +
		"typedef struct { Point* ptr; int len; int cap; } ogo_slice_Point;\n" +
		"struct Buf { int arr[3]; ogo_slice_Point pts; };\n" +
		"\n" +
		"int main(void) {\n" +
		"\tBuf b = {0};\n" +
		"\tPoint ogo_backing_0[2] = {0};\n" +
		"\tb.pts = (ogo_slice_Point){ogo_backing_0, 2, 2};\n" +
		"\tb.arr[0]++;\n" +
		"\tb.pts.ptr[1].x++;\n" +
		"\tPoint ogo_backing_1[2] = {0};\n" +
		"\togo_slice_Point s = {ogo_backing_1, 2, 2};\n" +
		"\ts.ptr[0].x--;\n" +
		"\tprintf(\"%d\\n\", (b.arr[0] + b.pts.ptr[1].x + s.ptr[0].x));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC indexed ++/--:\n got %q\nwant %q", got, want)
	}
}

