// TestEmitCArrayField pins fixed-size array struct fields, scalar-element
// (`vals [4]int`) and struct-element (`pts [3]Point`). Every array field used to
// fail with `unsupported type ""`, which mattered on a target with no heap, where
// a struct wrapping a fixed extent is the ordinary way to own storage.
//
// C puts the extent on the declarator, so the field cannot be emitted as the
// `ctype name` pair every other field uses; structField carries the bound
// separately and the typedef applies it here as `int vals[4]`.
func TestEmitCArrayField(t *testing.T) {
	src := `type Point struct {
	x int
	y int
}

type Grid struct {
	vals [4]int
	pts  [3]Point
	n    int
}

func main() {
	var g Grid
	g.vals[1] = 10
	g.pts[2].x = 32
	g.n = g.vals[1] + g.pts[2].x
	println(g.n)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <stdio.h>\n" +
		"\n" +
		"typedef struct Point Point;\ntypedef struct Grid Grid;\n" +
		"struct Point { int x; int y; };\nstruct Grid { int vals[4]; Point pts[3]; int n; };\n" +
		"\n" +
		"int main(void) {\n" +
		"\tGrid g = {0};\n" +
		"\tg.vals[1] = 10;\n" +
		"\tg.pts[2].x = 32;\n" +
		"\tg.n = (g.vals[1] + g.pts[2].x);\n" +
		"\tprintf(\"%d\\n\", g.n);\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC array struct field:\n got %q\nwant %q", got, want)
	}
}

