// TestEmitCSliceFieldStructElem pins a struct-element slice field `pts []Point`,
// the inverse of the scalar-element case: the ogo_slice_Point header names Point,
// so it must follow Point's typedef, yet Path holds it by value, so it must also
// precede Path's. It is emitted inline between the two, and the pinned order here
// (Point, ogo_slice_Point, Path) is the whole point of the test.
//
// A forward reference (`[]B` with B declared later) stays unsupported: the element
// resolves through cType, which fails on an unknown name -- the same declaration
// order rule that already governs a plain struct-typed field.
func TestEmitCSliceFieldStructElem(t *testing.T) {
	src := `type Point struct {
	x int
	y int
}

type Path struct {
	pts []Point
	n   int
}

func main() {
	var p Path
	p.pts = make([]Point, 2, 2)
	p.n = len(p.pts)
	r := p.pts[0]
	println(p.n + r.x)
}
`
	fsys := fstest.MapFS{"main.ogo": &fstest.MapFile{Data: []byte(src)}}
	pkg, err := Build(-1, []string{"main.ogo"}, fsys)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}

	var buf bytes.Buffer
	if err := EmitC(pkg, &buf); err != nil {
		t.Fatalf("EmitC: %v", err)
	}

	want := "// Code generated by ogo. DO NOT EDIT.\n" +
		"\n" +
		"#include <stdio.h>\n" +
		"\n" +
		"typedef struct Point Point;\n" +
		"typedef struct Path Path;\n" +
		"struct Point { int x; int y; };\n" +
		"typedef struct { Point* ptr; int len; int cap; } ogo_slice_Point;\n" +
		"struct Path { ogo_slice_Point pts; int n; };\n" +
		"\n" +
		"int main(void) {\n" +
		"\tPath p = {0};\n" +
		"\tPoint ogo_backing_0[2] = {0};\n" +
		"\tp.pts = (ogo_slice_Point){ogo_backing_0, 2, 2};\n" +
		"\tp.n = (p.pts).len;\n" +
		"\tPoint r = p.pts.ptr[0];\n" +
		"\tprintf(\"%d\\n\", (p.n + r.x));\n" +
		"\treturn 0;\n" +
		"}\n"
	if got := buf.String(); got != want {
		t.Errorf("EmitC struct-element slice field:\n got %q\nwant %q", got, want)
	}
}

